" fill="#6b21a8">4. Sarı Saltuk (Balkanlar / Dobruca)</text>\n  <text x="375" y="192" font-size="11" fill="#581c87">• Rumeli ve Balkanlar\'ın İslamlaşmasında öncü</text>\n  <text x="375" y="210" font-size="11" fill="#581c87">• Dobruca ve Kırım\'da zaviyeler kurmuştur.</text>\n  <text x="375" y="228" font-size="11" fill="#581c87">• Destansı hayatı: <tspan font-weight="bold">Saltuknâme</tspan></text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
